import{ICONES,MESSAGES,NATURES,TYPES,faits,quitter,retirer,setFait}from"./chunk-FRQP2J22.js";import{chargerIndex,chemin,resume,titre}from"./chunk-CFQST5AV.js";import{chapitreComplet,dansCombien,jourFr,lienChapitre,trouverMatiere}from"./chunk-EZ7JXTHG.js";import{RACINE}from"./chunk-MENTKLMX.js";import{echap}from"./chunk-CG5YCEWP.js";async function chargerDurees(items){items.some(it=>it&&it.type==="devoir")&&await chargerIndex()}var chapitre=chapitreComplet,matiere=trouverMatiere;function libelleCible(it){let c=chapitre(it.chapitre);if(it.type==="exercice")return(it.exercice&&it.exercice.titre?it.exercice.titre:"Un exercice")+(c?" · "+c.titre:"");if(it.type==="cours")return(it.section&&it.section.titre?it.section.titre:"Un point du cours")+(c?" · "+c.titre:"");if(it.type==="echeance"){let n=(NATURES.find(x=>x[0]===it.nature)||["","Échéance"])[1],chs=(it.chapitres||[]).map(id=>{let x=chapitre(id);return x?x.titre:id});return n+(chs.length?" · "+chs.join(", "):"")}if(it.type==="message"){let m=MESSAGES.find(x=>x[0]===it.message);return m?m[1]:""}return it.type==="devoir"?it.devoir?titre(Object.assign({},it.devoir,{echeance:""})):"Un devoir":""}function etiquette(it){return TYPES[it.type]||it.type}function lienCible(it){return it.type==="exercice"?lienChapitre(it.chapitre,it.exercice&&it.exercice.id):it.type==="cours"?lienChapitre(it.chapitre,it.section&&it.section.id):it.type==="echeance"&&it.chapitres&&it.chapitres.length===1?lienChapitre(it.chapitres[0],"entrainement"):it.type==="devoir"&&it.devoir?RACINE+chemin(it.devoir):null}function messageJoint(it){if(it.type==="message"||!it.message)return"";let m=MESSAGES.find(x=>x[0]===it.message);return m?'<span class="mot">« '+echap(m[1])+" »</span>":""}function rendreItem(it,opts){opts=opts||{};let f=faits(),url=lienCible(it),fait=f.has(it.id),quand=(it.type==="echeance"||it.type==="devoir")&&it.echeance?'<b class="quand">'+echap(jourFr(it.echeance,!0))+'</b><span class="discret"> · '+echap(dansCombien(it.echeance))+(it.type==="devoir"?" · "+echap(resume(it.devoir)):"")+"</span>":'<span class="discret">'+echap(jourFr(it.date))+"</span>",titre2=url?'<a href="'+echap(url)+'">'+echap(libelleCible(it))+"</a>":"<span>"+echap(libelleCible(it))+"</span>";return'<li class="carnet-item type-'+echap(it.type)+(fait?" fait":"")+'" data-item="'+echap(it.id)+'"><span class="ico" aria-hidden="true">'+ICONES[it.type]+'</span><div class="corps"><span class="etiq">'+echap(etiquette(it))+"</span>"+titre2+messageJoint(it)+'<span class="meta">'+quand+"</span></div>"+(opts.retirer?'<button type="button" class="btn fantome petit" data-retirer="'+echap(it.id)+'" aria-label="Retirer cet envoi">Retirer</button>':opts.lecture||it.type==="message"||it.type==="echeance"?"":'<label class="case-fait"><input type="checkbox" data-fait="'+echap(it.id)+'"'+(fait?" checked":"")+"><span>fait</span></label>")+"</li>"}function rendreRubrique(r,opts){opts=opts||{};let pr=r.prof,m=matiere(pr.matiere),couleur=m&&m.couleur||"neutre",tete='<header class="rubrique-tete" data-couleur="'+echap(couleur)+'"><span class="pastille" aria-hidden="true"></span><div><strong>'+echap(pr.prof)+'</strong><span class="discret">'+echap(m?m.nom:pr.matiere)+(pr.classe?" · "+echap(pr.classe):"")+"</span></div>"+(opts.quitter?'<button type="button" class="btn fantome petit" data-quitter="'+echap(pr.code)+'">Quitter cette classe</button>':"")+"</header>",corps=r.items.length?'<ul class="carnet-liste">'+r.items.map(it=>rendreItem(it,opts)).join("")+"</ul>":`<p class="discret vide">Rien pour l'instant. `+echap(pr.prof)+" n'a encore rien envoyé.</p>";return'<section class="rubrique-prof" data-code="'+echap(pr.code)+'">'+tete+corps+"</section>"}function brancher(el,opts){opts=opts||{},el.addEventListener("change",e=>{let c=e.target.closest("[data-fait]");if(!c)return;setFait(c.dataset.fait,c.checked);let li=c.closest(".carnet-item");li&&li.classList.toggle("fait",c.checked)}),el.addEventListener("click",e=>{let q=e.target.closest("[data-quitter]");if(q){q.dataset.confirme?(quitter(q.dataset.quitter),opts.apres&&opts.apres()):(q.dataset.confirme="1",q.textContent="Confirmer : quitter",q.classList.remove("fantome"));return}let r=e.target.closest("[data-retirer]");r&&opts.code&&(retirer(opts.code,r.dataset.retirer),opts.apres&&opts.apres())})}export{chargerDurees,libelleCible,etiquette,lienCible,rendreItem,rendreRubrique,brancher};
